/** Line weights at scale 1 (1920x1080). Sets match the character: dark outlines 3.5-4 px, no hairlines, no sketchy lines. */
export const STROKE = Object.freeze({
  outline: 4, // Pip's head, torso, hood, hands, shoes; set props
  propOutline: 3.5,
  limb: 12, // legs (arms 11), drawn as a light/dark core with a +7 px outline
  limbOutlineExtra: 7,
  face: 5, // eyes, brows, mouth
  labelBorder: 3.5, // pill/card border
  chalk: 6, // DrawOn diagram lines
  titleStroke: 13, // big title line; small line uses 9
});

